// Generated by vibelang from src/updates/updateChannels.ts; the migrate flow writes it again with each batch.
const NIGHTLY_VERSION_PATTERN = /^[^-+]+-nightly\.\d{8}\.\d+$/;
// Preview builds share nightly branding but ship without an update feed.
const PRERELEASE_VERSION_PATTERN = /^[^-+]+-(?:nightly|preview)\.\d{8}\.\d+$/;
export function isNightlyDesktopVersion(version) {
    return PRERELEASE_VERSION_PATTERN.test(version);
}
export function resolveDefaultDesktopUpdateChannel(appVersion) {
    return NIGHTLY_VERSION_PATTERN.test(appVersion) ? "nightly" : "latest";
}
